#include <bits/stdc++.h>
using namespace std;
int main(int argc,char**argv){int N=argc>1?atoi(argv[1]):9;for(int n=1;n<=N;n++){vector<array<unsigned char,12>> ps,inv;vector<int>a(n);function<void(int,int)> gen=[&](int at,int mx){if(at==n){for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)if(a[i]!=a[j])for(int k=j+1;k<n;k++)if(a[k]==a[i])for(int l=k+1;l<n;l++)if(a[l]==a[j])return;array<unsigned char,12>p{},q{};for(int i=0;i<n;i++){int j=(i+1)%n;while(a[j]!=a[i])j=(j+1)%n;p[i]=j;q[j]=i;}ps.push_back(p);inv.push_back(q);return;}for(int b=0;b<=mx+1;b++){a[at]=b;gen(at+1,max(mx,b));}};a[0]=0;gen(1,0);vector<int>count(ps.size());for(size_t i=0;i<ps.size();i++)for(size_t j=i+1;j<ps.size();j++){int x=0,len=0;do{x=ps[i][inv[j][x]];len++;}while(x&&len<=n);if(len==n){count[i]++;count[j]++;}}if(n==1)count[0]=1;int best=*max_element(count.begin(),count.end()),mult=count_if(count.begin(),count.end(),[&](int v){return v==best;});array<unsigned char,12>r{};for(int i=0;i<n;i++)r[i]=n-1-i;auto it=find_if(ps.begin(),ps.end(),[&](auto p){return equal(p.begin(),p.begin()+n,r.begin());});cout<<"n "<<n<<" Catalan "<<ps.size()<<" maximum "<<best<<" maximizers "<<mult<<" rainbow "<<(it==ps.end()?-1:count[it-ps.begin()])<<endl;}}
